import java.util.*;

public class Solution {
    // Dois TreeSet de índices (desempate por índice permite duplicatas). baixo tem k/2 + k%2 elementos.
    static double[] medianas(int[] nums, int k) {
        Comparator<Integer> cmp = (a, b) -> nums[a] != nums[b] ? Integer.compare(nums[a], nums[b]) : Integer.compare(a, b);
        TreeSet<Integer> baixo = new TreeSet<>(cmp), alto = new TreeSet<>(cmp);
        double[] out = new double[nums.length - k + 1];
        for (int i = 0; i < nums.length; i++) {
            if (i >= k && !baixo.remove(i - k)) alto.remove(i - k);
            baixo.add(i);
            alto.add(baixo.pollLast());
            while (baixo.size() < alto.size()) baixo.add(alto.pollFirst());
            if (i >= k - 1) {
                out[i - k + 1] = k % 2 == 1
                    ? nums[baixo.last()]
                    : ((long) nums[baixo.last()] + nums[alto.first()]) / 2.0;
            }
        }
        return out;
    }
}

