import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    private static double[] bruta(int[] a, int k) {
        double[] out = new double[a.length - k + 1];
        for (int i = 0; i + k <= a.length; i++) {
            int[] w = Arrays.copyOfRange(a, i, i + k);
            Arrays.sort(w);
            out[i] = k % 2 == 1 ? w[k / 2] : ((long) w[k / 2 - 1] + w[k / 2]) / 2.0;
        }
        return out;
    }

    @Test void exemplo() {
        assertArrayEquals(new double[]{1, -1, -1, 3, 5, 6}, Solution.medianas(new int[]{1, 3, -1, -3, 5, 3, 6, 7}, 3));
    }

    @Test void parEExtremos() {
        assertArrayEquals(new double[]{Integer.MAX_VALUE, -0.5},
            Solution.medianas(new int[]{Integer.MAX_VALUE, Integer.MAX_VALUE, Integer.MIN_VALUE}, 2));
    }

    @Test void aleatorioComDuplicatas() {
        var rnd = new Random(2);
        for (int t = 0; t < 200; t++) {
            int n = 1 + rnd.nextInt(30), k = 1 + rnd.nextInt(n);
            int[] a = rnd.ints(n, 0, 6).toArray();
            assertArrayEquals(bruta(a, k), Solution.medianas(a, k), Arrays.toString(a) + " k=" + k);
        }
    }

    @Test void grande() {
        int[] a = new Random(3).ints(100_000).toArray();
        assertEquals(100_000 - 1000 + 1, Solution.medianas(a, 1000).length);
    }
}
